	m.agentsErr = false
	settled := !m.fullPending && m.agg.Activity().Settled(msg.at, quietPeriod)
	m.clock = statusClock{now: msg.at, alive: !settled}
	u := m.usage
	if msg.delta.Full() || !msg.delta.Empty() {
